"""Shared, responsive presentation for the IBROWS-managed produce marketplace."""
START = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="theme-color" content="#124c38"><title>{{ page_title|default('Farm Produce Marketplace') }} | IBROWS Enterprise</title>
<style>
:root{--ink:#162d25;--muted:#586b61;--green:#14523d;--green-dark:#0b3828;--soft:#ecf5ee;--line:#dce5dd;--paper:#fff;--bg:#f6f7f3;--gold:#c9aa67}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}a{color:var(--green);text-underline-offset:4px}button,input,textarea,select{font:inherit}a,button,input,textarea,select{touch-action:manipulation}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #b98b29;outline-offset:3px}button,.button{min-height:48px;display:inline-flex;justify-content:center;align-items:center;gap:8px;border:1px solid var(--green);border-radius:9px;background:var(--green);color:white;padding:11px 20px;font-weight:700;text-decoration:none;cursor:pointer;line-height:1.4}button:hover,.button:hover{background:var(--green-dark)}.button.secondary{background:transparent;color:var(--green);border-color:var(--line)}.button.secondary:hover{background:var(--soft)}.container{width:min(1120px,calc(100% - 64px));margin-inline:auto}.site-header{background:white;border-bottom:1px solid var(--line)}.header-inner{min-height:88px;display:flex;align-items:center;justify-content:space-between;gap:24px}.brand{color:var(--green-dark);text-decoration:none;font-weight:850;letter-spacing:.06em;font-size:25px;line-height:1.2}.brand small{display:block;font-size:10px;letter-spacing:.22em;font-weight:650;margin-top:5px}.header-nav{display:flex;gap:28px;align-items:center}.header-nav a{font-size:14px;font-weight:600;text-decoration:none}.header-nav .button{padding:10px 16px;min-height:42px}.hero{padding:52px 0 32px;display:grid;grid-template-columns:minmax(0,1.7fr) minmax(240px,1fr);gap:50px;align-items:center}.eyebrow{font-size:11px;letter-spacing:.16em;font-weight:800;text-transform:uppercase;color:var(--green);margin:0 0 12px}.hero h1,.page-heading h1{font-size:clamp(32px,4.2vw,48px);line-height:1.12;letter-spacing:-.045em;margin:0 0 18px;font-weight:750;max-width:680px}.hero h1 span{color:var(--green)}.intro{color:var(--muted);margin:0;max-width:610px;line-height:1.75}.service-note{border-left:3px solid var(--gold);padding:8px 0 8px 22px}.service-note strong{display:block;font-size:15px;margin-bottom:7px}.service-note p{font-size:14px;line-height:1.7;margin:0;color:var(--muted)}.search-panel{background:var(--paper);border:1px solid var(--line);padding:23px 26px;border-radius:14px;display:grid;grid-template-columns:1fr 1fr auto;gap:18px;align-items:end;box-shadow:0 5px 24px #163b2410}.field{display:flex;flex-direction:column;gap:7px;min-width:0}.field label,.field>span{font-size:12px;font-weight:750;color:#354b40}input:not([type=checkbox]):not([type=hidden]),textarea,select{width:100%;min-height:48px;border:1px solid #ccd8ce;border-radius:8px;background:#fff;padding:11px 13px;color:var(--ink);min-width:0}input::placeholder,textarea::placeholder{color:#718076;opacity:1}textarea{min-height:130px;resize:vertical}.results-header{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:34px 0 18px}.results-header h2{margin:0;font-size:20px;letter-spacing:-.02em}.results-header p{margin:0;font-size:13px;color:var(--muted)}.results-header a{font-size:13px}.produce-list{display:grid;gap:20px}.produce-card{background:var(--paper);border:1px solid var(--line);border-radius:16px;overflow:hidden;box-shadow:0 3px 12px #0d302006}.card-top{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:18px 26px;border-bottom:1px solid #e8eee8}.card-top .eyebrow{margin:0}.badge{display:inline-flex;align-items:center;gap:7px;font-size:11px;font-weight:750;background:var(--soft);color:var(--green);border-radius:30px;padding:5px 11px}.badge.available:before{content:"";width:6px;height:6px;background:#27835b;border-radius:50%}.badge.neutral{background:#f0f1ed;color:#58664f}.card-body{display:grid;grid-template-columns:1.1fr 1fr 1fr;gap:24px;padding:28px 26px 30px;align-items:start}.produce-title{font-size:26px;letter-spacing:-.035em;line-height:1.2;margin:0 0 14px;font-weight:750}.grade{color:var(--muted);font-size:13px;margin:0 0 12px}.stock{font-size:17px;font-weight:700;margin:0 0 2px}.pack{color:var(--muted);font-size:13px;margin:0}.detail-label{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em;margin:0 0 8px;font-weight:700}.location{font-size:15px;line-height:1.7;margin:0;font-weight:600;overflow-wrap:anywhere}.description{font-size:14px;color:var(--muted);margin:14px 0 0;overflow-wrap:anywhere}.purchase{border-left:1px solid var(--line);padding-left:26px}.price{font-size:29px;letter-spacing:-.04em;line-height:1.2;font-weight:780;margin:0 0 5px;white-space:nowrap}.price-unit{font-size:13px;color:var(--muted);margin:0 0 20px}.purchase .button{width:100%;font-size:13px;padding:12px 14px}.small-note{font-size:11px;color:var(--muted);line-height:1.65;margin:10px 0 0}.how-it-works{display:grid;grid-template-columns:repeat(3,1fr);gap:30px;padding:30px 0;margin-top:30px;border-top:1px solid var(--line)}.step-label{color:var(--green);font-size:11px;letter-spacing:.12em;font-weight:800;margin-right:8px}.how-it-works h3{font-size:14px;margin:0 0 6px}.how-it-works p{font-size:13px;color:var(--muted);margin:0;line-height:1.7}.site-footer{margin-top:35px;padding:24px 0;border-top:1px solid var(--line);font-size:12px;color:var(--muted)}.footer-inner{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap}.empty{background:white;border:1px dashed #bdcfc0;border-radius:14px;padding:42px 26px;text-align:center}.empty h3{margin:0 0 10px;font-size:20px}.empty p{margin:0 0 20px;color:var(--muted)}.page-heading{padding:38px 0 24px}.back-link{font-size:13px;display:inline-block;margin-bottom:24px}.page-heading h1{font-size:36px}.page-heading .intro{font-size:15px}.form-layout{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(230px,1fr);gap:28px;align-items:start}.panel{background:white;border:1px solid var(--line);border-radius:14px;padding:28px}.panel h2{font-size:19px;line-height:1.4;margin:0 0 20px;letter-spacing:-.02em}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}.full{grid-column:1/-1}.check{display:flex;align-items:flex-start;gap:12px;font-size:13px;color:var(--muted);line-height:1.7}.check input{width:18px;height:18px;flex-shrink:0;accent-color:var(--green);margin-top:3px}.form-actions{display:flex;align-items:center;gap:16px;flex-wrap:wrap;margin-top:24px}.form-actions a{font-size:13px}.side-panel{background:#edf3eb;border:1px solid #dae6d9}.side-panel p{font-size:14px;color:var(--muted);margin:0 0 20px}.side-panel p:last-child{margin-bottom:0}.side-panel h3{font-size:14px;margin:0 0 7px}.error{padding:14px 16px;background:#fff0ed;border:1px solid #f0c4bb;border-radius:8px;color:#8b3027;font-size:14px;margin-bottom:22px}.honeypot{display:none}.confirmation{max-width:680px;margin:58px auto 20px;padding:42px}.confirmation h1{font-size:36px;letter-spacing:-.04em;margin:14px 0}.reference{background:var(--soft);padding:15px 20px;border-radius:9px;margin:24px 0;font-size:15px}.reference strong{display:block;font-size:19px;margin-top:4px}.admin-card .card-body{grid-template-columns:1fr 1.4fr}.admin-controls{display:grid;grid-template-columns:1fr 1fr auto;gap:14px;align-items:end}.admin-help{font-size:13px;color:var(--muted);margin:18px 0 0}.summary{margin:0;display:grid;grid-template-columns:1fr 1fr;gap:18px}.summary dt{font-size:12px;color:var(--muted)}.summary dd{margin:4px 0 0;font-weight:650;font-size:15px}.text-link{font-size:13px}.notice{padding:16px 20px;background:var(--soft);border-radius:10px;color:var(--green);font-size:14px;margin:0 0 24px}
@media(min-width:1000px){.hero{padding-top:60px;padding-bottom:38px}}
@media(max-width:900px){.container{width:calc(100% - 40px)}.hero{gap:28px}.card-body{grid-template-columns:1fr 1fr}.purchase{grid-column:1/-1;border-left:0;border-top:1px solid var(--line);padding:20px 0 0;display:grid;grid-template-columns:1fr 1fr;column-gap:25px}.purchase .price-unit{grid-column:1;margin:0}.purchase .button{grid-column:2;grid-row:1/3;align-self:center}.purchase .small-note{grid-column:1/-1}.admin-card .card-body{grid-template-columns:1fr}.form-layout{grid-template-columns:1fr}.side-panel{display:grid;grid-template-columns:1fr 1fr;gap:20px}.side-panel h2{grid-column:1/-1;margin-bottom:0}.side-panel p{margin:0}}
@media(max-width:620px){.container{width:calc(100% - 32px)}.header-inner{min-height:78px;gap:16px}.brand{font-size:21px}.brand small{font-size:8px}.header-nav{gap:15px}.header-nav .desktop-link{display:none}.header-nav .button{font-size:12px;padding:9px 12px;min-height:40px}.hero{display:block;padding:32px 0 26px}.hero h1{font-size:36px}.intro{font-size:14px}.service-note{margin-top:18px;padding:0;border:0}.service-note strong{display:none}.service-note p{font-size:12px}.search-panel{padding:20px;grid-template-columns:1fr;gap:15px}.search-panel button{width:100%}.results-header{margin:28px 0 16px;align-items:start}.results-header h2{font-size:18px}.results-header p{font-size:12px;margin-top:4px}.card-top{padding:15px 20px}.card-body{padding:23px 20px;grid-template-columns:1fr;gap:20px}.produce-title{font-size:26px;margin-bottom:12px}.detail-label{margin-bottom:4px}.location{font-size:14px}.purchase{display:block;grid-column:auto;padding-top:22px}.price{font-size:30px}.purchase .price-unit{margin:5px 0 18px}.purchase .button{font-size:14px}.how-it-works{grid-template-columns:1fr;gap:20px;padding:25px 0;margin-top:26px}.site-footer{margin-top:12px}.panel{padding:22px}.form-grid{grid-template-columns:1fr;gap:20px}.page-heading{padding-top:25px}.page-heading h1{font-size:30px}.side-panel{display:block}.side-panel p{margin-bottom:20px}.side-panel h2{margin-bottom:20px}.admin-controls{grid-template-columns:1fr 1fr}.admin-controls button{grid-column:1/-1}.confirmation{margin-top:30px;padding:28px}.confirmation h1{font-size:30px}.summary{grid-template-columns:1fr}.form-actions .button,.form-actions button{width:100%}}
</style></head><body>
<header class="site-header"><div class="container header-inner"><a class="brand" href="/" aria-label="IBROWS Enterprise home">IBROWS<small>ENTERPRISE</small></a><nav class="header-nav" aria-label="Main navigation"><a class="desktop-link" href="/agriculture">Agriculture</a><a class="desktop-link" href="/agriculture/marketplace">Marketplace</a><a class="button secondary" href="/agriculture">Sell your produce</a></nav></div></header>
<main class="container" id="main-content">'''
END = '''</main><footer class="site-footer"><div class="container footer-inner"><span>IBROWS Enterprise · Agriculture Marketplace</span><a href="/privacy">Privacy policy</a></div></footer></body></html>'''

CATALOGUE = START + r'''
<section class="hero" aria-labelledby="page-title"><div><p class="eyebrow">IBROWS AGRICULTURE</p><h1 id="page-title">Farm produce.<br><span>Handled by IBROWS.</span></h1><p class="intro">Find produce, check quantities and enquire with IBROWS. We confirm stock, price and collection or delivery details.</p></div><aside class="service-note"><strong>One point of contact. From enquiry to coordination.</strong><p>All enquiries are handled by IBROWS. Seller contact details stay private.</p></aside></section>
<form class="search-panel" method="get" aria-label="Search farm produce"><div class="field"><label for="commodity">Produce</label><input id="commodity" name="commodity" placeholder="e.g. maize, soya, groundnuts" value="{{ commodity }}"></div><div class="field"><label for="location">Location</label><input id="location" name="location" placeholder="District or area" value="{{ location }}"></div><button type="submit">Find produce</button></form>
<div class="results-header"><div><h2>Available produce</h2><p>{{ rows|length }} listing{{ '' if rows|length == 1 else 's' }}{% if commodity or location %} matching your search{% endif %}</p></div>{% if commodity or location %}<a href="{{ url_for('agro_marketplace.catalogue') }}">Clear filters</a>{% endif %}</div>
<div class="produce-list">{% for p in rows %}{% set stock = p[3]|agro_stock(p[4]) %}<article class="produce-card"><div class="card-top"><p class="eyebrow">FARM PRODUCE</p><span class="badge available">Available</span></div><div class="card-body"><div><h2 class="produce-title">{{p[1]}}</h2>{% if p[2] and (p[2]|lower) not in (p[1]|lower) %}<p class="grade">Grade / variety: {{p[2]}}</p>{% endif %}<p class="stock">{{stock.amount}} {{stock.unit}} available</p>{% if stock.pack %}<p class="pack">{{stock.pack}}</p>{% endif %}</div><div><p class="detail-label">Location</p><p class="location">{{p[7]}}</p>{% if p[8] %}<p class="description">{{p[8]}}</p>{% endif %}</div><div class="purchase"><p class="price">{% if p[5] is not none %}MK {{'{:,.0f}'.format(p[5])}}{% else %}On enquiry{% endif %}</p><p class="price-unit">{% if p[5] is not none %}per {{p[6] or p[4]}}{% else %}Ask IBROWS for the current price{% endif %}</p><a class="button" href="{{ url_for('agro_marketplace.buyer_enquiry', listing_id=p[0]) }}">Enquire through IBROWS</a><p class="small-note">Stock and final price confirmed by our team.</p></div></div></article>{% else %}<section class="empty"><h3>{% if commodity or location %}No produce matches your search{% else %}More produce is on the way{% endif %}</h3><p>{% if commodity or location %}Try another produce name or a nearby location.{% else %}Available listings appear here after review by IBROWS.{% endif %}</p><a class="button secondary" href="{% if commodity or location %}/agriculture/marketplace{% else %}/agriculture{% endif %}">{% if commodity or location %}View all produce{% else %}Tell us what you need{% endif %}</a></section>{% endfor %}</div>
<section class="how-it-works" aria-label="How buying works"><div><h3><span class="step-label">01</span>Find your produce</h3><p>Compare the quantity, bag size, price and location.</p></div><div><h3><span class="step-label">02</span>Enquire with IBROWS</h3><p>Tell our team how much you need and how to reach you.</p></div><div><h3><span class="step-label">03</span>Confirm the details</h3><p>We confirm availability and discuss arrangements with you.</p></div></section>
''' + END

ENQUIRY = START + r'''
<div class="page-heading"><a class="back-link" href="/agriculture/marketplace">← Back to available produce</a><p class="eyebrow">BUYER ENQUIRY</p><h1>Enquire about {{listing[1]}}</h1><p class="intro">Let IBROWS know what you need. Our team will contact you to discuss availability and the next steps.</p></div>
<div class="form-layout"><section class="panel"><h2>Your contact details</h2>{% if error %}<p class="error" role="alert">{{error}}</p>{% endif %}<form method="post"><input type="hidden" name="csrf_token" value="{{csrf}}"><input class="honeypot" name="fax_number" tabindex="-1" autocomplete="off" aria-hidden="true"><div class="form-grid"><div class="field"><label for="buyer-name">Full name <span aria-hidden="true">*</span></label><input id="buyer-name" name="name" autocomplete="name" maxlength="180" required value="{{request.form.get('name','')}}"></div><div class="field"><label for="buyer-phone">Phone number <span aria-hidden="true">*</span></label><input id="buyer-phone" name="phone" type="tel" autocomplete="tel" placeholder="e.g. +265 888 123 456" maxlength="80" required value="{{request.form.get('phone','')}}"></div><div class="field full"><label for="buyer-message">What would you like to arrange?</label><textarea id="buyer-message" name="message" maxlength="2000" placeholder="Tell us the quantity you need, your area and any collection or delivery preferences.">{{request.form.get('message','')}}</textarea></div><label class="check full"><input type="checkbox" name="consent" value="1" required{% if request.form.get('consent')=='1' %} checked{% endif %}><span>I consent to IBROWS contacting me about this enquiry. My contact details will not be published.</span></label></div><div class="form-actions"><button type="submit">Send enquiry to IBROWS</button><a href="/agriculture/marketplace">Back to produce</a></div></form></section><aside class="panel side-panel"><h2>Handled by IBROWS</h2><div><h3>Availability first</h3><p>We confirm the available stock and current price before any transaction is agreed.</p></div><div><h3>Your details stay private</h3><p>This enquiry goes to the IBROWS team. Your phone number does not appear on the marketplace.</p></div></aside></div>
''' + END

SUCCESS = START + r'''
<section class="panel confirmation"><span class="badge available">Sent to IBROWS</span><h1>Enquiry received</h1><p class="intro">Thank you. IBROWS will contact you to discuss the produce and confirm the arrangements.</p><div class="reference">Your enquiry reference<strong>AG-BUY-{{id}}</strong></div><p class="small-note">This is an enquiry. Availability, final price and collection or delivery details still need to be confirmed.</p><div class="form-actions"><a class="button" href="/agriculture/marketplace">Back to available produce</a></div></section>
''' + END

MODERATION = START + r'''
<div class="page-heading"><a class="back-link" href="/admin/service-requests">← Buyer enquiries and service requests</a><p class="eyebrow">IBROWS ADMINISTRATION</p><h1>Manage produce listings</h1><p class="intro">Keep available quantities and listing status up to date. Approved listings with remaining stock appear on the marketplace.</p></div>
<p class="notice">Before approving, confirm seller permission, current stock and price. Set remaining stock to 0 to mark a listing sold out.</p>
<div class="results-header"><h2>{{rows|length}} listing{{ '' if rows|length==1 else 's' }}</h2><a href="/agriculture/marketplace">View public marketplace</a></div>
<div class="produce-list">{% for p in rows %}{% set stock = p[2]|agro_stock(p[3]) %}<section class="produce-card admin-card"><div class="card-top"><p class="eyebrow">LISTING #{{p[0]}}</p><span class="badge{% if p[5]!='APPROVED' %} neutral{% endif %}">{{p[5]|replace('_',' ')|title}}</span></div><div class="card-body"><div><h2 class="produce-title">{{p[1]}}</h2><p class="stock">{{stock.amount}} {{stock.unit}} remaining</p>{% if stock.pack %}<p class="pack">{{stock.pack}}</p>{% endif %}<p class="description">{{p[4]}}</p></div><div><form class="admin-controls" method="post"><input type="hidden" name="csrf_token" value="{{csrf}}"><input type="hidden" name="listing_id" value="{{p[0]}}"><div class="field"><label for="stock-{{p[0]}}">Remaining stock ({{stock.unit}})</label><input id="stock-{{p[0]}}" name="quantity" type="number" min="0" step="0.001" required value="{{p[2]|agro_quantity}}"></div><div class="field"><label for="status-{{p[0]}}">Listing status</label><select id="status-{{p[0]}}" name="status">{% for s in ['APPROVED','REJECTED','PAUSED','SOLD_OUT'] %}<option value="{{s}}"{% if s==p[5] %} selected{% endif %}>{{s|replace('_',' ')|title}}</option>{% endfor %}</select></div><button type="submit">Save changes</button></form><p class="admin-help">Pause to temporarily hide a listing. Saving stock does not reserve or sell any produce.</p></div></div></section>{% else %}<section class="empty"><h3>No produce listings yet</h3><p>Review an agricultural seller request to create a pending listing.</p><a class="button" href="/admin/service-requests">Review service requests</a></section>{% endfor %}</div>
''' + END

IMPORT = START + r'''
<div class="page-heading"><a class="back-link" href="/admin/agro-marketplace">← Back to produce management</a><p class="eyebrow">IBROWS ADMINISTRATION</p><h1>Prepare a produce listing</h1><p class="intro">Review the seller request and confirm the price before creating a pending listing.</p></div>
<div class="form-layout"><section class="panel"><h2>Seller request {{ref}}</h2><dl class="summary"><div><dt>Produce</dt><dd>{{commodity}}</dd></div><div><dt>Quantity supplied in request</dt><dd>{% set stock = qty|agro_stock(unit) %}{{stock.amount}} {{stock.unit}}{% if stock.pack %}<br><span class="pack">{{stock.pack}}</span>{% endif %}</dd></div><div class="full"><dt>Location</dt><dd>{{location}}</dd></div></dl><hr style="border:0;border-top:1px solid var(--line);margin:25px 0"><form method="post"><input type="hidden" name="csrf_token" value="{{csrf}}"><div class="form-grid"><div class="field"><label for="listing-price">Price in MWK *</label><input id="listing-price" name="price_mwk" type="number" min="1" step="0.01" required></div><div class="field"><label for="listing-price-unit">Price per *</label><input id="listing-price-unit" name="price_unit" required placeholder="e.g. 50 kg bag"></div><label class="check full"><input type="checkbox" name="confirm" value="yes" required><span>I have verified the quantity, price and availability.</span></label><label class="check full"><input type="checkbox" name="seller_consent" value="yes" required><span>The seller has explicitly authorized IBROWS to advertise this produce.</span></label></div><div class="form-actions"><button>Create pending listing</button></div></form></section><aside class="panel side-panel"><h2>Review before publishing</h2><div><h3>Pending first</h3><p>Creating this listing does not publish it. Approval is a separate step in produce management.</p></div><div><h3>Private seller contacts</h3><p>Buyers enquire through IBROWS. The seller's contact details will not appear on the public listing.</p></div></aside></div>
''' + END
